-- Rifts World Book 27: Adventures in Dinosaur Swamp - its bestiary and its notable NPCs.
-- 0 creatures (migration 074) and 3 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~259-adventures-in-dinosaur-swamp-camps.sql
--
-- Written by scripts/bestiary-sql.mjs from 1 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.

INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('deearn-neenok', 'Deearn Neenok', 'Deearn Neenok', 'Leader of the 2nd Neenok Expedition', 'rifts', 'A''rac, spider-like D-Bee', '9th level Rogue Scholar', 9, 'Scrupulous', '59', '7 feet (2.1 m)', '207 lbs (93 kg)', '{"IQ":20,"ME":10,"MA":17,"PS":15,"PP":12,"PE":22,"PB":6,"Spd":14}', 52, 83, NULL, 8, NULL, 13, NULL, '{"attacks":6,"strike":1,"parry":2,"dodge":2,"damage":2,"roll":2,"pull":2}', 'Hand to Hand: Basic. +4 on Perception Rolls. Critical Strike on a natural 19-20. +2 vs Horror Factor, +3 vs disease, +10 vs poison. Skill figures already include +6% to all skills and +5% to Science and Technical skills. P.S. is the equivalent of Bionic Strength. P.B. 6 to humans and human-like D-Bees, 12 to other A''rac. Natural A.R. 13: a roll of 1-13 does no Hit Point or S.D.C. damage. Can take one M.D. point of damage and survive. Male. Occupation: adventurer and college professor.', '[{"name":"Literacy","pct":98},{"name":"Language: American","pct":98},{"name":"Language: Euro","pct":98},{"name":"Language: Spanish","pct":98},{"name":"Basic Math","pct":98},{"name":"Computer Operation","pct":98},{"name":"Pilot Automobile","pct":92},{"name":"Advanced Math","pct":98},{"name":"Anthropology","pct":81},{"name":"Archaeology","pct":81},{"name":"Biology","pct":91},{"name":"Botany","pct":86},{"name":"Xenology (North America, Europe)","pct":91},{"name":"Writing","pct":98},{"name":"Mining","pct":98},{"name":"History (North American, European)","pct":98},{"name":"Lore: Magic","pct":96},{"name":"Lore: D-Bee","pct":96},{"name":"Lore: Demons & Monsters","pct":96},{"name":"Research","pct":98},{"name":"Photography","pct":98},{"name":"Prowl","pct":81},{"name":"Wilderness Survival","pct":81}]', 'W.P. Energy Pistol, W.P. Energy Rifle, W.P. Revolver, W.P. Submachine-gun.', 'Natural climbing 90%/90%, excellent balance, and sight into the infrared and ultraviolet spectrum.', 'Lore only.', 'Lore only. No I.S.P. printed.', NULL, NULL, 'NG-45LP "Long Pistol" in a right-hand side-draw holster on a utility belt; Wilk''s-Remi 130 "Six Shooter" (a gift from Obioma) in a hip holster; Urban Warrior - Padded Environmental Body Armor in the field, painted brown and tan. A backpack and shoulder satchel hold magnifying lenses, notepad and pens, spare E-Clips, a Portable Language Translator, a few books, a pocket digital camera and sound recorder (6 hours of sound, 2000 pictures per disc), and his Wilk''s EVC-600 video camera: 3 lbs (1.35 kg), waterproof and shockproof with 22 M.D.C., two canisters of 48 hours of sound and video each, macro, zoom and telescopic lenses and filters, built-in editing, and jacks for computers, broadcast systems and bionic head and finger jacks; 20,000 credits.', NULL, 'A born explorer who fears no unknown land: upbeat, eager, in love with discovery, research and scholarly writing, and restless after too many years at home. He has made peace with the deaths on his first expedition, and they have made him more careful in planning every trip since.', NULL, NULL, 'A seven-foot spider-like A''rac whose face has mandibles and four insect eyes, with slender fingers and skin of fine iridescent plates, born at Lazlo in 50 P.A. to parents who helped found its university. He led New Lazlo''s first expedition into Dinosaur Swamp (82-84 P.A.), from which only 40% came home, wrote a 1200-page field study of it (87 P.A.), and in 109 P.A. leads the second. The video camera seldom leaves his hand.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.107-109'),
('obioma-aardan-kwu', 'Obioma Aardan-kwu', 'Obioma Aardan-kwu', 'Second in command of the 2nd Neenok Expedition', 'rifts', 'Aardan Tek', '9th level Rogue Scientist', 9, 'Principled', '62', '6 feet, 5 inches (1.9 m)', '190 lbs (86 kg)', '{"IQ":14,"ME":19,"MA":14,"PS":15,"PP":18,"PE":14,"PB":3,"Spd":14}', 53, 41, NULL, 15, 44, 13, NULL, '{"attacks":6,"initiative":3,"strike":2,"parry":6,"dodge":6,"roll":4,"pull":2}', 'Hand to Hand: Expert. Critical Strike on a natural 18-20. +2 to save vs Horror Factor, +2 vs psionics, +2 vs insanity. M.D.C. by armor only. Male. Occupation: professional adventurer.', '[{"name":"Literacy","pct":98},{"name":"Language: American","pct":98},{"name":"Language: Dragonese/Elven","pct":98},{"name":"Language: Spanish","pct":98},{"name":"Language: Japanese","pct":98},{"name":"Computer Operation","pct":98},{"name":"Advanced Math","pct":98},{"name":"Read Sensory Equipment","pct":90},{"name":"Basic Electronics","pct":90},{"name":"Pilot Automobile","pct":86},{"name":"Pilot Jet Pack","pct":79},{"name":"Biology","pct":90},{"name":"Botany","pct":85},{"name":"Xenology: North American","pct":90},{"name":"Chemistry","pct":90},{"name":"Chemistry: Analytical","pct":85},{"name":"Prowl","pct":65},{"name":"Lore: Demons & Monsters","pct":80},{"name":"Paramedic","pct":85}]', 'Athletics, W.P. Energy Rifle, W.P. Sword, W.P. Archery & Targeting, W.P. Paired Weapons. Lore: Demons & Monsters is printed as 80 with no percent sign.', 'Scent: 94% to know a common scent, 74% to pick out a specific odor, 66% to Track by Smell; Land Navigation 80%.', 'Lore only.', 'Minor psionic: Total Recall and Astral Projection. I.S.P. 44.', NULL, NULL, 'The Bandito (light body armor), 54 M.D.C., painted in grays and greens to match his skin; a Wilk''s 457 Laser Pulse Rifle, his preferred energy weapon; a Vibro-Sword in a hip scabbard. Travels light and keeps most gear stowed in a vehicle; on his utility belt, a canteen, survival knife and a hip-pack with flashlight, cigarette lighter, matches, compass, pocket mirror, a clove of garlic, a small silver cross, a P.D.D. recorder, notepad and pen.', '10,000 credits on hand, plus 90,000 credits and 182,000 credits in artifacts put away for his retirement.', 'A clear-headed, ethical thinker who relishes a challenge of mind or body alike, and enjoys a hard workout as much as a hard math problem.', NULL, NULL, 'A trunk-nosed Aardan Tek and dimensional traveler who reached Rifts Earth around 67 P.A., befriended Neenok at Lazlo''s university and was his second in command on the first expedition (82 P.A.). After years in Africa, where he fought the Phoenix Empire at the Gathering of Heroes, he holds the same post on the second. Athletic, he dresses loosely for freedom of movement.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.112-113'),
('alexander-washington-lee', 'Alexander Washington Lee', 'Alexander Washington Lee', 'Quartermaster and Captain of the Scout Forces, 2nd Neenok Expedition', 'rifts', NULL, '8th level Mutant Barbarian Swamp Stomper', 8, 'Principled', '27', 'Six feet (1.8 m)', '200 lbs (90 kg)', '{"IQ":14,"ME":19,"MA":15,"PS":21,"PP":13,"PE":19,"PB":15,"Spd":14}', 36, 52, NULL, 5, NULL, NULL, NULL, '{"attacks":6,"initiative":2,"strike":1,"parry":5,"dodge":5,"damage":6,"roll":4,"pull":4}', 'Hand to Hand: Basic and Boxing. The damage bonus is to S.D.C. damage. Critical Strike on a natural 19-20. +2 to save vs psionic attacks, +2 vs magic, +4 vs poison, +4 vs Horror Factor, +7 on Perception Rolls; 40% charm/impress. M.D.C. by armor only. Male.', '[{"name":"Cooking","pct":75},{"name":"Climbing","pct":95},{"name":"Language: Spanish","pct":98},{"name":"Language: Gobblely","pct":98},{"name":"Language: American (Southern Dialect)","pct":98},{"name":"Land Navigation","pct":84},{"name":"Horsemanship: General","pct":88},{"name":"Identify Plants","pct":80},{"name":"Fishing","pct":85},{"name":"Prowl","pct":80},{"name":"Swimming","pct":95},{"name":"Track Animals","pct":86},{"name":"Wilderness Survival","pct":85},{"name":"Animal Husbandry","pct":80},{"name":"Holistic Medicine","pct":75},{"name":"Jury-Rig","pct":75},{"name":"Pilot Motorcycle","pct":88}]', 'Athletics, Hunting, Stalking, W.P. Knife, W.P. Energy Rifle, W.P. Energy Pistol, W.P. Bolt-Action Rifle, W.P. Automatic Pistol. The book prints Hunting, Stalking, Fishing 85% as one run; the 85% is stored on Fishing.', 'Heightened Sense of Hearing (distance 80%; speed and direction 65%; a known voice or sound 65%). Heightened Sense of Smell (a specific odor 75%; tracking by scent alone 55%). Natural Poison/Disease Resistance 90%.', 'None.', 'None.', NULL, NULL, 'Savage Pump-Action Rifle (Viggo); two steel blue .45 automatic pistols in hip holsters; a vibro skinning knife (Vibro-Knife); a battered, often-repaired L-20 Pulse Rifle. Explorer Armor, full environmental, 65 M.D.C., when traveling; camouflage fatigues when hunting or scouting. A utility belt with harness and a backpack of survival gear; everything else rides in cargo containers on his King Grizzly KG-ATV4 4-Wheel ATV.', NULL, 'Quiet, even-tempered and slow to anger; a methodical planner who never rushes and still tends to finish early.', NULL, NULL, 'A trim, bearded, light-skinned barbarian from a tribe in the Virginia Appalachian foothills, with none of the visible mutations common in the eastern tribes. Sent out in his early teens with his uncle, the Wilderness Scout H.B. Lee, he spent a decade hiring out across the west as guide, courier, hunter and gunman, and means to go home and lead his tribe once the expedition ends in 112 P.A.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.113-114');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 3 notable NPCs are in' AS assertion, count(*) AS got, 3 AS want
  FROM notable_npcs WHERE slug IN ('deearn-neenok', 'obioma-aardan-kwu', 'alexander-washington-lee');
SELECT 'and the notables 0' AS assertion, count(*) AS got, 0 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('deearn-neenok', 'obioma-aardan-kwu', 'alexander-washington-lee');

